from __future__ import absolute_import
from builtins import object
from builtins import str
import os
from taf.ul.trs_e2e_fw.lib.oam.coam_cbts_cu.factory import Factory
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.global_vars import global_vars
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from IPy import IP

logger = BackgroundLogger.Instance()


class BaseClass(object):

    def __init__(self):
        self.factory = Factory.get_instance()

    def setup_oamops(self, **kwargs):
        logger.info("through interface :: {}".format(str(kwargs.get(
            "execute_through_interface", False))))
        alias = kwargs.get("alias", "default")
        if alias not in list(global_vars.alias_dut_dict.keys()):
            dut = kwargs.pop("dut", "bts")
            use_ssl = kwargs.pop("use_ssl", True)
            cu_version = kwargs.pop("cu_version", 'cuoam_19b')
            # admin_api_log_dir = kwargs.pop("admin_api_log_dir", "execution_logs")
            timeout = kwargs.pop("timeout", 3000)
            alias = kwargs.pop("alias", "default")
            bts_host, bts_port, username, password, cu_version = self._get_bts_params_from_arguments(dut, kwargs)
            bts_host = self._format_ipv6_ipaddress(bts_host)
            self.factory.cu_oam.connect_to(host=bts_host, port=bts_port, username=username, password=password,
                                           secure=use_ssl, alias=alias, cu_version=cu_version, timeout=timeout)
        global_vars.admin_alias = alias
        # Use only non-chain setup alias for internal admin usage
        global_vars.setup_admin_called = True

    def _get_bts_params_from_arguments(self, dut, kwargs):
        # User given arguments over-ride config parameters
        bts_host = kwargs.pop('bts_host', get_config_variable([dut, 'oam', 'ip']))
        bts_port = kwargs.pop('bts_port', get_config_variable([dut, 'oam', 'webem_port']))
        username = kwargs.pop('username', get_config_variable([dut, 'oam', 'webem_user']))
        password = kwargs.pop('password', get_config_variable([dut, 'oam', 'webem_password']))
        cu_version = kwargs.pop('cu_version', get_config_variable([dut, 'oam', 'cu_version']))
        logger.debug(
            "BTS Credentials obtained... \nbts_host::{0}\nbts_port::{1}\n"
            "username::{2}\npassword::{3}\ncu_version{4}".format(bts_host, bts_port, username, password, cu_version))
        return bts_host, bts_port, username, password, cu_version

    def get_delta_file_full_path(self, delta_file, alias):
        delta_dir = get_config_variable(['delta_files'])
        bts_id, delta_dir = self.get_config_files_from_corresponding_bts_dir(
            delta_dir, alias)
        return os.path.join(delta_dir, delta_file)

    def get_config_files_from_corresponding_bts_dir(self, bts_config_file_path,
                                                    alias):
        """
            This function returns bts config files like scf_file and delta_file
            etc. from the config directory of the primary bts or chain bts
        """
        # logger.debug("obtaining scf full path...")
        chained = global_vars.alias_chained_dict.get(alias)
        dut = global_vars.alias_dut_dict.get(alias)

        bts_id = get_config_variable(['bts_id'])

        if chained:
            chained_bts_id = get_config_variable([dut, 'bts_id'])
            # scf_dir = _get_config_variable(['chained_bts_scf_dir']).format(
            #     chained=bts_id)
            bts_config_file_path = bts_config_file_path.replace('/{}/'.format(
                bts_id), '/{}/'.format(chained_bts_id))
            bts_id = chained_bts_id
        return bts_id, bts_config_file_path

    def teardown_oamops(self, **kwargs):
        alias = kwargs.get('alias', 'default')
        self.factory.cu_oam.disconnect(connection=alias)

    def _format_ipv6_ipaddress(self, bts_host):
        ip_object = IP(bts_host)
        if ip_object.version() == 6:
            return '[{}]'.format(str(ip_object))
            # Add square brackets around for IPv6 addresses
        return bts_host

    def _verify_status(self, param, status):
        if param['status'].lower() == status.lower():
            return True
        return False
